SELECT posting_date,item_code,warehouse,voucher_type,voucher_no,actual_qty,qty_after_transaction,valuation_rate,stock_value_difference FROM "tabStock Ledger Entry" WHERE (%(company)s = '' OR company = %(company)s) AND (%(from_date)s = '' OR posting_date >= %(from_date)s) AND (%(to_date)s = '' OR posting_date <= %(to_date)s) AND (%(item_code)s='' OR item_code=%(item_code)s) AND (%(warehouse)s='' OR warehouse=%(warehouse)s) ORDER BY posting_date,name
